package com.eventos.api.config;
import com.eventos.api.security.JwtFilter; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.*; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration @EnableWebSecurity public class SecurityConfig extends WebSecurityConfigurerAdapter { private final JwtFilter filter; public SecurityConfig(JwtFilter filter){this.filter=filter;} @Bean public PasswordEncoder encoder(){return new BCryptPasswordEncoder();} protected void configure(HttpSecurity http)throws Exception {http.csrf().disable().cors().and().sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS).and().authorizeRequests().antMatchers("/api/auth/**","/v2/api-docs","/swagger-ui/**","/swagger-resources/**","/webjars/**","/h2-console/**").permitAll().anyRequest().authenticated().and().headers().frameOptions().sameOrigin();http.addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class);} }
